-- Extracted from the owner's October 27 marketplace reference images.
-- Each icon is tied to an exact item name, tier, rarity and equipment slot.
-- Never guess the missing glove icon; do not mutate current equipment ownership.
ON CONFLICT (item_id) DO UPDATE SET
item_name=EXCLUDED.item_name, slot=EXCLUDED.slot, rarity=EXCLUDED.rarity,
tier=EXCLUDED.tier,equipment_kind=EXCLUDED.equipment_kind,job_class=EXCLUDED.job_class,
icon_asset=EXCLUDED.icon_asset,sprite_index=EXCLUDED.sprite_index,
sprite_columns=EXCLUDED.sprite_columns,icon_verified=EXCLUDED.icon_verified,
updated_at=now();
